'use client';

import { useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { useFirebase } from '@/context/FirebaseContext';
import LeftBar from '@/legacy_pages/LeftBar';
import ChatHeader from '@/features/chat/components/ChatHeader';
import ChatContainer from '@/features/chat/ChatContainer';
import MessageInput from '@/features/chat/components/MessageInput';

export default function ChatPage() {
    const firebase = useFirebase();
    const router = useRouter();

    // Auth check
    useEffect(() => {
        const unsubscribe = firebase.onAuthStateChanged((user) => {
            if (!user) router.push('/');
        });

        return () => {
            if (typeof unsubscribe === 'function') {
                (unsubscribe as Function)();
            }
        };
    }, [firebase, router]);

    return (
        <div className="h-screen bg-black overflow-hidden flex flex-col lg:flex-row">
            {/* Desktop Sidebar - Hidden on mobile/tablet */}
            <div className="hidden lg:block h-full lg:w-1/3 xl:w-[350px]">
                <LeftBar width={0} />
            </div>

            {/* Main Chat Area */}
            <div className="flex flex-col h-full w-full lg:flex-1 relative">
                {/* Mobile Header - Hidden on Desktop (optional, or keep visible) */}
                <div className="lg:hidden z-50">
                    <ChatHeader />
                </div>

                <div className="flex-1 overflow-hidden relative flex flex-col">
                    <ChatContainer />
                    <MessageInput />
                </div>
            </div>
        </div>
    );
}
