'use client';

import { useRef, useEffect } from 'react';
import useChat from '@/hooks/useChat';
import BackgroundLetterAvatars from "@/shared/components/Avatar";
import { useTheme } from '@/context/ThemeContext';
import { Alert } from '@mui/material';
import { useParams } from 'next/navigation';

const ChatContainer = () => {
  const params = useParams();
  const roomId = params?.roomId as string;
  const { theme } = useTheme();

  const {
    messages,
    newMember,
    kickoutMember,
    logoutMember,
    username,
    currentUser
  } = useChat(roomId);

  const chattingRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    const container = chattingRef.current;
    if (container) {
      container.scrollTop = container.scrollHeight;
    }
  };

  // Scroll on new message
  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleDownload = (url: string | null | undefined, filename: string) => {
    if (!url) return;
    try {
      const a = document.createElement("a");
      a.href = url;
      a.download = filename || "download";
      document.body.appendChild(a);
      a.click();
      a.remove();
    } catch (err) {
      console.error("Download failed:", err);
    }
  };



  const renderSystemAlert = () => {
    if (newMember) {
      return (
        <Alert severity="success">
          New Member: <span className="username">{newMember}</span> joined successfully!
        </Alert>
      );
    }
    if (kickoutMember) {
      return (
        <Alert severity="info">
          Member Left: <span className="username">{kickoutMember}</span> was kicked out!
        </Alert>
      );
    }
    if (logoutMember) {
      return (
        <Alert severity="info">
          Member Left: <span className="username">{logoutMember}</span> left the room!
        </Alert>
      );
    }
    return null;
  };

  return (
    <div className={`${theme === 'light' ? 'light-rev' : 'dark'} flex-1 h-full min-h-0 w-full relative`}>
      <div
        className={`${newMember || kickoutMember || logoutMember ? 'flex' : 'hidden'
          } z-30 sm:justify-center mt-2 sm:w-fit absolute sm:left-1/2`}
      >
        {renderSystemAlert()}
      </div>

      <div
        className="main-container px-4 hide-scroll-bar scroll-smooth"
        ref={chattingRef}
        style={{ overflowY: 'auto', height: '100%' }}
      >
        {messages.map((m, i) => {
          const isUser = m.username === username || m.id === currentUser;
          const msgClass = isUser ? 'user' : 'member';
          const msgStyle = isUser ? 'user-msg' : 'member-msg';

          return (
            <div key={`msg-${i}`} className={msgClass}>
              <div>
                {m.download ? (
                  <div className={`overflow-hidden msg ${msgStyle}`}>
                    <div
                      className={`flex flex-col items-center bg-[#1e293b] hover:bg-[#334155] transition-all duration-200 rounded-lg p-2 gap-2 cursor-pointer`}
                      onClick={() => handleDownload(m.download, m.message)}
                    >
                      {/* {getMediaElement(m, i)} */}
                      <p className="text-white text-sm break-words max-w-[200px] text-center">
                        {m.message}
                      </p>
                    </div>
                  </div>
                ) : (
                  <h1
                    className={`msg ${msgStyle}`}
                    style={{ minWidth: "40px" }}
                  >
                    {m.message}
                  </h1>
                )}
                <div
                  className={`time ${isUser ? "justify-end" : "justify-start"
                    } flex items-center gap-2`}
                >
                  {!isUser && (
                    <>
                      <BackgroundLetterAvatars
                        username={m.username}
                        size="10px"
                      />
                      <p className="font-semibold">~ {m.username}</p>
                    </>
                  )}
                  <span>{m.time}</span>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default ChatContainer;
