import * as React from 'react';
import Avatar from '@mui/material/Avatar';

function stringToColor(string: string) {
  let hash = 0;
  let i;

  /* eslint-disable no-bitwise */
  for (i = 0; i < string.length; i += 1) {
    hash = string.charCodeAt(i) + ((hash << 5) - hash);
  }

  let color = '#';

  for (i = 0; i < 3; i += 1) {
    const value = (hash >> (i * 8)) & 0xff;
    color += `00${value.toString(16)}`.slice(-2);
  }
  /* eslint-enable no-bitwise */

  return color;
}

function stringAvatar(name: string, size: string) {
  return {
    sx: {
      bgcolor: stringToColor(name),
      width: size,
      height: size,
    },
    children: `${name.charAt(0)}`,
  };
}

interface BackgroundLetterAvatarsProps {
  username?: string;
  size?: string;
}

export default function BackgroundLetterAvatars({ username = "U", size = "40px" }: BackgroundLetterAvatarsProps) {
  return (
    <Avatar {...stringAvatar(username, size)} style={{ padding: "12px" }} />
  );
}
