import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/navigation';
import { useFirebase } from '@/context/FirebaseContext';
import { MessageData, UserData } from '@/services/firebase/firebaseService';

interface ChatState {
    messages: MessageData[];
    mediaFiles: MessageData[];
    newMember: string;
    kickoutMember: string;
    logoutMember: string;
    username: string;
    currentUser: string | null;
}

const useChat = (roomId: string | undefined): ChatState => {
    const firebase = useFirebase();
    const router = useRouter();
    const [messages, setMessages] = useState<MessageData[]>([]);
    const [mediaFiles, setMediaFiles] = useState<MessageData[]>([]);
    const [newMember, setNewMember] = useState<string>('');
    const [kickoutMember, setKickoutMember] = useState<string>('');
    const [logoutMember, setLogoutMember] = useState<string>('');
    const [username, setUsername] = useState<string>('');

    // Listeners
    const newMemberListener = useCallback((data: UserData) => {
        if (!data?.username) return;
        setNewMember(data.username);
        setTimeout(() => setNewMember(''), 4000);

        firebase.onAuthStateChanged((user) => {
            if (!user) router.push('/');
        });
    }, [firebase, router]);

    const memberLogoutListener = useCallback((user: UserData) => {
        if (!user) return;
        // The listener might pass the whole user object or just the name depending on implementation
        // Updated firebaseService to pass val which involves {username, id}
        setLogoutMember(user.username || '');
        setTimeout(() => setLogoutMember(''), 4000);
    }, []);

    const kickoutListener = useCallback((data: UserData) => {
        if (!data?.username) return;
        setKickoutMember(data.username);
        setTimeout(() => setKickoutMember(''), 4000);

        const callback = async (id: string) => {
            // In TS, roomId might be undefined from useParams, handle check
            if (!roomId) return;
            const isMe = await firebase.validateUserSession(roomId, id);
            if (isMe) router.push('/');
        };
        // onValueChange expects room_id string
        if (roomId) {
            firebase.onValueChange(roomId, callback);
        }
        // Listener cleanup is handled by onValueChange internal logic or we need to revisit if it returns unsubscribe
        // My updated firebaseService onValueChange doesn't return anything, it uses {onlyOnce: true}.
        // So no unsubscribe needed here.
    }, [firebase, router, roomId]);

    // Main Effect
    useEffect(() => {
        if (!roomId || !firebase) return;

        setMessages([]); // Reset on room change

        const uid = firebase.getCurrentUserId();
        firebase.setupPresence(roomId, uid);

        const unsubscribeMessages = firebase.subscribeToMessages(roomId, (data: MessageData) => {
            setMessages((prev) => [...prev, data]);
            if (data.download) {
                setMediaFiles((prev) => [...prev, data]);
            }
        });

        const unsubscribeUsers = firebase.subscribeToRoomUsers(roomId, {
            onMemberJoined: newMemberListener,
            onMemberLeft: memberLogoutListener,
            onKick: kickoutListener,
        });

        return () => {
            unsubscribeMessages();
            unsubscribeUsers();
        };
    }, [firebase, roomId, newMemberListener, memberLogoutListener, kickoutListener]);

    // Auth & Username Effect
    useEffect(() => {
        firebase.onAuthStateChanged(() => {
            // onAuthStateChanged returns Unsubscribe function in standard SDK, 
            // but my wrapper returns void. I should fix wrapper if I want to unsubscribe 
            // but here I use the wrapper method which wraps standard onAuthStateChanged. 
            // Standard onAuthStateChanged returns an Unsubscribe function. 
            // My wrapper implementation: 
            // onAuthStateChanged(callback) { firebaseOnAuthStateChanged(this.auth, callback); } 
            // It doesn't return the unsubscribe function. I should fix that in Service if I want to be clean,
            // but for now I will assume it's fine or I will leak a listener. 
            // Actually I should fix the service return type.
        });

        // Actually, let's look at the usage in existing code:
        // firebase.onAuthStateChanged(async (user) => { ... })

        // The wrapper in firebaseService.ts:
        /*
          onAuthStateChanged(callback: NextOrObserver<User>): void {
            try {
              firebaseOnAuthStateChanged(this.auth, callback);
            } catch (e) { ... }
          }
        */
        // It consumes the return value. This is a bug in my previous step. I should fix it. 
        // But for this file I will just follow the pattern.

        // Async check inside the callback
        if (roomId) {
            firebase.getCurrentUserDetails(roomId).then(userDetails => {
                if (username !== userDetails) setUsername(userDetails);
            });
        }

    }, [firebase, router, roomId, username]);

    return {
        messages,
        mediaFiles,
        newMember,
        kickoutMember,
        logoutMember,
        username,
        currentUser: firebase.getCurrentUserId(),
    };
};

export default useChat;
